def valid(text):
    """题面：首行 N M（1<=N<=100，1<=M<=10^3）；后续恰好 M 行 u v w（1<=u,v<=N，1<=w<=10^5）。
    另外要求 N>=2：N=1 时“存在孤立节点”与“已全连通（代价 0）”两种读法冲突，数据避开。"""
    lines = text.split('\n')
