def valid(text):
    """题面：第一行 n（1<=n<=1000）；接下来 n 行各一个整数 ri（-128<=ri<=127）；
    再 n-1 行，每行 l k（1<=l,k<=n），k 是 l 的直接上司；关系保证是一棵树。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    try:
        if len(lines[0].split()) != 1:
            return False
        n = int(lines[0])
        if not 1 <= n <= 1000 or len(lines) != 2 * n:
            return False
        for line in lines[1:n + 1]:
            toks = line.split()
            if len(toks) != 1 or not -128 <= int(toks[0]) <= 127:
                return False
        parent = [0] * (n + 1)
        for line in lines[n + 1:]:
            toks = line.split()
            if len(toks) != 2:
                return False
            l, k = map(int, toks)
            if not (1 <= l <= n and 1 <= k <= n) or l == k or parent[l]:
                return False
            parent[l] = k
    except ValueError:
        return False
    roots = [v for v in range(1, n + 1) if not parent[v]]
    if len(roots) != 1:
        return False
    # 无环：从每个点沿上司走，必须走到根
    state = [0] * (n + 1)          # 0 未访问，1 在路径上，2 已确认可达根
    state[roots[0]] = 2
    for v in range(1, n + 1):
        path = []
        while state[v] == 0:
            state[v] = 1; path.append(v); v = parent[v]
        if state[v] == 1:
            return False
        for u in path:
            state[u] = 2
    return True

