    """题面契约：恰四行；首行 N L M，1<=N<=10^6，2<=L<=10^5，2<=M<=100；
    其后三行各 N 个整数，0<=cost<=M。"""
    import re
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    if len(lines) != 4:
        return False
    num = re.compile(r'0|[1-9][0-9]*')
