def valid(text):
    """题面契约：两行。第一行高精度正整数 n（不超过 250 位，无前导零）；第二行正整数 k，
    删去 k 个数字后要剩下数字 -> 1 <= k < n 的位数。题面样例第一行带一个行尾空格，
    所以行尾空格放行，其余格式严格。"""
    if not text.endswith("\n"):
        return False
    rows = text[:-1].split("\n")
    if len(rows) != 2:
        return False
    n, k = rows[0].rstrip(" "), rows[1].rstrip(" ")
    if not (n.isdigit() and k.isdigit()) or n[0] == "0" or k != str(int(k)):
        return False
    return len(n) <= 250 and 1 <= int(k) < len(n)

def valid(text):
    """题面：两行；第一行 N M（2 ≤ N,M ≤ 1000）；第二行 M 个小于 N 的非负整数。"""
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    if len(lines) != 2 or not _re.fullmatch(r'\d+ \d+', lines[0]):
        return False
    n, m = map(int, lines[0].split())
    if not (2 <= n <= 1000 and 2 <= m <= 1000):
        return False
    toks = lines[1].split(' ')
    if len(toks) != m or not all(_re.fullmatch(r'0|[1-9]\d*', t) for t in toks):
        return False
    return all(int(t) < n for t in toks)

def valid(text):
    """题面：一行整数，1 ≤ nums.length ≤ 15，-100 ≤ nums[i] ≤ 100。"""
    if not text.endswith('\n') or text.count('\n') != 1:
        return False
    toks = text[:-1].split(' ')
    if not (1 <= len(toks) <= 15):
        return False
    if not all(_re.fullmatch(r'-?(0|[1-9]\d*)', t) and t != '-0' for t in toks):
        return False
    return all(-100 <= int(t) <= 100 for t in toks)

def valid(text):
    """题面：共 n+2 行；第一行 w（80 ≤ w ≤ 200）；第二行 n（1 ≤ n ≤ 3×10^4）；
    其后 n 行每行一个正整数 Pi（5 ≤ Pi ≤ w）。题面样例行末带空格，故允许行末空格。"""
    if not text.endswith('\n'):
        return False
    lines = [l.rstrip(' ') for l in text[:-1].split('\n')]
    if len(lines) < 2 or not all(_re.fullmatch(r'[1-9]\d*', l) for l in lines):
        return False
    w, n = int(lines[0]), int(lines[1])
    if not (80 <= w <= 200 and 1 <= n <= 30000) or len(lines) != n + 2:
        return False
    return all(5 <= int(p) <= w for p in lines[2:])

